<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';const username=ref(''),password=ref(''),loading=ref(false),router=useRouter(),s=useAuthStore();async function submit(){loading.value=true;try{await s.login(username.value,password.value);router.push('/dashboard')}finally{loading.value=false}}</script><template><main class="login"><section><h1>IIOP</h1><p>工业设备智能巡检运维平台</p><el-form @submit.prevent="submit"><el-input v-model="username" placeholder="用户名"/><el-input v-model="password" type="password" show-password placeholder="密码"/><el-button type="primary" :loading="loading" native-type="submit">登录平台</el-button></el-form></section></main></template>
